def kin(n, l): return -(a2/(2*n**4))*(n/(l+.5)-.75)
def so(n, l, j): return 0 if l == 0 else (a2/(2*n**3))*(j*(j+1)-l*(l+1)-.75)/(2*l*(l+.5)*(l+1))
